import torch

class SGDWithDecoupledWeightDecay:
    def __init__(self, params, lr=0.01, weight_decay=0.0):
        self.params = list(params)
        self.lr = lr
        self.weight_decay = weight_decay

    def step(self):
        with torch.no_grad():
            for p in self.params:
                if p.grad is None:
                    continue
                # direct weight decay, NOT added into p.grad
                p.mul_(1 - self.lr * self.weight_decay)
                p.add_(p.grad, alpha=-self.lr)

    def zero_grad(self):
        for p in self.params:
            if p.grad is not None:
                p.grad.zero_()


if __name__ == '__main__':
    import torch.nn as nn
    model = nn.Linear(4, 1)
    opt = SGDWithDecoupledWeightDecay(model.parameters(), lr=0.1, weight_decay=0.01)

    x = torch.randn(8, 4); y = torch.randn(8, 1)
    for _ in range(5):
        opt.zero_grad()
        loss = ((model(x) - y) ** 2).mean()
        loss.backward()
        opt.step()
    print('trained weight:', model.weight)

import torch
import torch.nn as nn
import json

ACTIVATIONS = {"relu": nn.ReLU, "gelu": nn.GELU, "tanh": nn.Tanh, "sigmoid": nn.Sigmoid}
NORMS = {"batch": nn.BatchNorm1d, "layer": nn.LayerNorm, "none": None}

class ConfigurableMLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        # config example:
        # {"input_dim": 20, "layers": [
        #     {"size": 64, "activation": "relu", "dropout": 0.2, "norm": "batch"},
        #     {"size": 32, "activation": "relu", "dropout": 0.1, "norm": "none"}],
        #  "output_dim": 1}
        self.blocks = nn.ModuleList()
        prev = config["input_dim"]
        for layer_cfg in config["layers"]:
            block = nn.ModuleList()
            size = layer_cfg["size"]
            block.append(nn.Linear(prev, size))
            norm_cls = NORMS.get(layer_cfg.get("norm", "none"))
            if norm_cls is not None:
                block.append(norm_cls(size))
            block.append(ACTIVATIONS[layer_cfg["activation"]]())
            if layer_cfg.get("dropout", 0) > 0:
                block.append(nn.Dropout(layer_cfg["dropout"]))
            self.blocks.append(block)
            prev = size
        self.output_layer = nn.Linear(prev, config["output_dim"])

    def forward(self, x):
        for block in self.blocks:
            for layer in block:
                x = layer(x)
        return self.output_layer(x)


if __name__ == '__main__':
