import torch
import torch.nn as nn

class ResidualBlock(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.fc1 = nn.Linear(dim, dim)
        self.fc2 = nn.Linear(dim, dim)
        self.act = nn.ReLU()

    def forward(self, x):
        out = self.act(self.fc1(x))
        out = self.fc2(out)
        return self.act(out + x)  # skip connection

class ResidualMLP(nn.Module):
    def __init__(self, dim, num_blocks):
        super().__init__()
        self.blocks = nn.ModuleList([ResidualBlock(dim) for _ in range(num_blocks)])

    def forward(self, x):
        for block in self.blocks:
            x = block(x)
        return x

class PlainMLP(nn.Module):
    def __init__(self, dim, num_layers):
        super().__init__()
        layers = []
        for _ in range(num_layers):
            layers += [nn.Linear(dim, dim), nn.ReLU()]
        self.net = nn.Sequential(*layers)

    def forward(self, x):
        return self.net(x)


def first_layer_grad_norm(model, x, y):
    loss = ((model(x) - y) ** 2).mean()
    loss.backward()
    first_param = next(model.parameters())
    return first_param.grad.norm().item()


if __name__ == '__main__':
    torch.manual_seed(0)
    dim = 32
    x = torch.randn(16, dim)
    y = torch.randn(16, dim)

    res_model = ResidualMLP(dim, num_blocks=10)
    plain_model = PlainMLP(dim, num_layers=20)

    print('Residual MLP first-layer grad norm:', first_layer_grad_norm(res_model, x, y))
    print('Plain MLP first-layer grad norm:', first_layer_grad_norm(plain_model, x, y))

import torch
import torch.nn as nn

def build_deep_mlp(dim, depth, init_fn):
    layers = []
    for _ in range(depth):
        linear = nn.Linear(dim, dim)
        init_fn(linear.weight)
        nn.init.zeros_(linear.bias)
        layers += [linear, nn.ReLU()]
    return nn.Sequential(*layers)


def measure_first_layer_grad(model, x, y):
    model.zero_grad()
    loss = ((model(x) - y) ** 2).mean()
    loss.backward()
    return next(model.parameters()).grad.norm().item()


if __name__ == '__main__':
    torch.manual_seed(0)
    dim, depth = 64, 20
    x = torch.randn(32, dim)
    y = torch.randn(32, dim)

    inits = {
        'orthogonal': lambda w: nn.init.orthogonal_(w),
        'xavier': lambda w: nn.init.xavier_normal_(w),
        'he': lambda w: nn.init.kaiming_normal_(w, nonlinearity='relu'),
    }

    for name, init_fn in inits.items():
        model = build_deep_mlp(dim, depth, init_fn)
        grad_norm = measure_first_layer_grad(model, x, y)
        print(f'{name}: first-layer grad norm = {grad_norm:.6f}')
